using System;

namespace StdbModule;

public static partial class TurkishQuotes
{
    public static class OğuzAtay
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Başkalarının yaptıklarını silmeye çalıştım: mürekkeple yazmışlar oysa. Ben, kurşunkalem silgisiydim. Azaldığımla kaldım.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Hayatım, ciddiye alınmasını istediğim bir oyundu. Sen evlendin ve oyunu bozdun. Bütün hayatımca nasıl oynayabilirdim? Sen de dayanabildin mi? Sen de ürkütücü bir gerçekle bozdun bu oyunu. Herkesin belirli bir işle uğraştığı bu kocaman dünyada yalnız başına oradan oraya sürüklendin canım kardeşim benim.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Kelimeden önce de Yalnızlık vardı. Ve Kelimeden sonra da var olmaya devam etti Yalnızlık... Kelimenin bittiği yerde başladı; Kelime söylenemeden önce başladı. Kelimeler, Yalnızlığı unutturdu ve Yalnızlık, Kelimeyle birlikte yaşadı insanın içinde. Kelimeler, Yalnızlığı anlattı ve Yalnızlığın içinde eriyip kayboldu. Yalnız Kelimeler acıyı dindirdi ve Kelimeler insanın aklına geldikçe, Yalnızlık büyüdü, dayanılmaz oldu.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "seni tanıdığıma çok sevindim kendi çapımda.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Bütün hayatımızı yersiz çekingenliklerle mi geçireceğiz Olric? Cesareti yalnız kafamızda mı yaşayacağız?", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Kendi sorunlarını çözemeyen bir kişinin, kusurlarının acısını başkalarına çektirmeye hakkı yoktur.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "İşte sonum geldi… Kötü bir resim asarım korkusuyla hiç resim asmadım; kötü yaşarım korkusuyla hiç yaşamadım.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Bana yaşamayı öğretmediler. Daha doğrusu, bana her şeyin öğrenilerek yaşanacağını öğrettiler. Yaşanırken öğrenileceğini öğretmediler. Ben de kolayca razı oldum bana öğretilen bu yanlışlara. İnsan, kendi bulurmuş doğru yolu. Ben bulamazdım. Bana, başkalarına gösterdikleri basmakalıp yolları öğrettiler. Başka türlü bir itinayla tutmalıydılar beni. Daha fazla değil, farklı.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Normal bir insan olmaya zorladılar, bana boş yere vakit kaybettirdiler. Olmayınca da, anormal dediler. Ben de kendimi anlamadım: Bütün hayatım boyunca normal bir adam olmaya çalıştım.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Selim Işık yalnızlığa dayanamazdı. İlk bakışta, yalnızlığın ve çevreyle uyuşmazlığın, yaşantısında önemli bir yer tuttuğu kolayca ileri sürülebilirdi. Selim, bu yargıya da dayanamazdı. Bütün dünya, ona dargın olabilirdi; fakat bu, aceleyle varılmış bir sonuçtu. Kimse onun kadar çevresine yakınlık duyamazdı.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Ne gördün bütün kapıların birer birer kapandığı bu dünyada? Hangi kusurunu düzeltmene fırsat verdiler? Son durağa gelmeden yolculuğun bitmek üzere olduğunu haber verdiler mi sana? Birdenbire: “Buraya kadar!” dediler. Oysa, bilseydin nasıl dikkatle bakardın istasyonlara; pencereden görünen hiçbir ağacı, hiçbir gökyüzü parçasını kaçırmazdın. Bütün sularda gölgeni seyrederdin. Üstelik, daha önce haber vermiştik, derler onlar. Her şeyin bir sonu olduğunu genel olarak belirtmiştik. Yaşarken eskidiğini ve eskittiğini söylemiştik. Sevginin ölümünü her pazar çanlar çalarak ilan etmiştik. İşte onların kanunları böyle. Bizimkilere benzeyebilir mi hiç? Şehrin duvarlarına sırayla üç kere ilan asıyorlar: sevginize dikkat! Dördüncüde ilan ve sevgiyi kaldırıveriyorlar. Onlarla başa çıkılmaz Turgut. Ben çıkabildim mi?", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Hiçbir şeyi unutmadı ve her olaydan, hayatının sonuna kadar rahatsız oldu.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Tutunamayanların destanıdır bu şarkı, Dostum Süleyman Kargı.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Çare.......... bulunacaktır.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Beni anlamalısın. Çünkü ben kitap değilim, çünkü ben öldükten sonra kimse beni okuyamaz, yaşarken anlaşılmaya mecburum.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Ülkemiz büyük bir oyun yeridir. Her sabah uyanınca biraz isteksiz de olsak, hepimiz sahnenin bir yerinde, bizi çevreleyen büyük ve uzak bir dünyanın sevimli bir benzerini kurmak için toplanırız. Küçük topluluklar olarak, birbirimizden bağımsız davranarak ve birbirimizi seyrederek günlük oyunlarımıza başlarız. (...) İnsanlarımız aynı piyesi yıllardır aynı biçimde oynamanın yorgunluğu ve gerçeğe bir türlü benzetememenin bezginliği içindeyken ben, bizlere bugüne kadar hiç yararı dokunmamış aklın -daha doğrusu, akıl olduğunu sandığımız akıl taklidinin- zincirlerinden kurtularak, bütün ülkeleri ve onların gerçek kişilerini içine alan büyük oyunun heyecanı içinde bulunuyorum.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Kelimeler, albayım. bazı anlamlara gelmiyor.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Bu düzmece oyun sona ermeli. Kendi benliğimizi bulmalıyız. Yol verip yakarmaktan vazgeçmeliyiz. Rüyalarımızı gerçekleştirmeye çalışmamalıyız, gerçekleri rüya yapmalıyız. Çelişiksiz dikensiz ve düzgün rüyalarımızı yaşamalıyız. Sözümüzün eri olmalıyız: Kırılacak kafaları kırmalıyız. Bize acınmadığı için acımamalıyız.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Sakın kimseye böyle bir oyun oynama oğlum, dedi. Onun köle olduğunu bildikten sonra ne zevk alıcaksın bu işten? Anlamıyorsunuz ki. Öyle olmadığına inandırcak beni. İnsan kolay inanır kölelere. Ben de bir zamanlar kölelik yaptım albayım: çok başarılıydım.Ücretim az geldiği için ayrılmak zorunda kaldım. Sonra da başka ekmek kapısı bulamadım. Gerçek köleleri çok iyi bilirim bu yüzden. Kimse beni kandıramaz bu konuda. Fakat, yorucu bi' iştir albayım: herkes beceremez. Biraz önce saydığım gereksiz ayrıntılardan kurtulmuş gerçek bir köle bulmak, gerçek bir arkadaş bulmak kadar zordur. Tabii ben arkadaş istemiyorum, köle istiyorum albayım.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Fakat oyunları unutacak albayım, yaşamak istiyorsa unutacak. Sadece ağladığını ve bir zamanlar çok mutsuz olduğunu hatırlayacak.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Yahuda ne yaptıysa kendine yaptı dedi Hikmet, İsa için üzücü olan, Yahuda'nın ihaneti değildi: neden yaşadığını hiç bilmeyen bu zavallı hain, neden intihar ettiğini de anlayamadan ölüp gitmişti. İsa işte buna üzülüyordu.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Eşyanın sürekliliğinden çekiniyorum. Bu sürekliliğin kendisine bulaşmasından korkuyordu. Yaklaş onlara, dokunmaya çalış. Onlarla uyuşmaya çalış. Hayır, kaybolurum sonra, eşyanın içine düşerim. Bilge de onların arasında. Bilge'ye ulaşmak için, onların arasından geçmek zorundasın. Olmaz, ben yalnız Bilge'yi istiyorum. Bilge her yere kök salmış, ayıramazsın Bilge'yi onlardan-, sonra çok acı duyar. Bilge beni dinliyor. O başka. Yüzünde, ilgiye benzer bir şeyler var. Senin gibi değil Bilge: Eşyayı ve seni birlikte seviyor. Fakat ben eşya gibi olamam. Eşyanın belirli kuralları var Ne zaman ne yapacağı belli Ben, istesem de, bunu beceremem. Böyle olduğumu Bilge'ye anlatsam mı? Sakın ha. Ya anlarsa? Deli misin? Eşya, seni eleverecek değil ya. Ya sorarsa? O kadar biliyorsun. Nasıl biliyorum? Biliyorsun işte: Devetabanı ne renk? Neresi? Yaprakları canım. Yeşil. Gördün mü? Sen, kaldığın yerden devam et sözlerine. Bu duraklamanın neden olduğunu anlamadı, değil mi? Duraklama bile olmadı. Sen konuş.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Bir şeyden yana değiliz ki Hayri dedi hüzünle, Bir parti kuralım. Şoför Hayri şiddetle içini çekti: Ah bir olabilseydik ağabeyciğim, biz de bir şeyden yana olabilseydik. Tuğrul, Ya da bir şeyler bizden yana olsaydı, diye tamamladı.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Beni anlamıyorlardı. Zarar yok. Zaten beni, daha kimler anlamadı.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Her şeye yeniden başlamak mümkün değildi. İstesem de mümkün değildi. Nerede kaldığımı unuttuğuma göre, baştan başlamak için de birtakım yetenekler gerekliydi; daha talihli doğmuş olmak gerekliydi mesela.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "İyi şeyler birdenbire olur; bu kadar bekletmez insanı. Sürüncemede kalan heyecanlardan ancak kötü şeyler çıkar. Ya da hiçbir şey çıkmaz.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Yalnız insanların kendi içinde başlayıp biten eğlenceleri vardır.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Ben buradayım sevgili okuyucum, sen neredesin acaba?", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Param vardı, yiyeceğim vardı, kitabım, evim her şeyim vardı; fakat isteğim yoktu.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Kelimeler bile yanyana gelerek beni tanımlamak istemezlerdi.", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Selim gibi, günlük tutmaya başlayalım bakalım. Sonumuz hayırlı değil herhalde onun gibi. Bu defteri bugün satın aldım. Artık Sevin olmadığına göre ve başka kimseyle konuşmak istemediğime göre, bu defter kaydetsin beni; dert ortağım olsun. Kimseye söyleyemeden, içimde kaldı, kayboldu, dediğim düşüncelerin, duyguların aynası olsun. Kimse dinlemiyorsa beni - ya da istediğim gibi dinlemiyorsa- günlük tutmaktan başka çare kalmıyor. Canım insanlar! Sonunda, bana, bunu da yaptınız!", Author = "Oğuz Atay" },
            new Quote { Id = "https://tr.wikiquote.org/wiki/Oğuz_Atay", Text = "Ya çocuksu gururumuz! Beğenilmezsek hemen alınıyoruz, Batılılara iftiralar ederek kendimizi temize çıkarmak için didiniyoruz. İyi aile çocukları aramızda, onlara çamur atan mahalle çocuğu gibiyiz.", Author = "Oğuz Atay" },
        };
    }
}